const upsertSocialSettings = `-- name: UpsertSocialSettings :one
INSERT INTO social_settings(user_id, visible, updated_at)
VALUES (?1, ?2, ?3)
ON CONFLICT(user_id) DO UPDATE SET visible = excluded.visible, updated_at = excluded.updated_at
RETURNING user_id, visible, updated_at
`

type UpsertSocialSettingsParams struct {
	UserID    int64
	Visible   bool
	UpdatedAt time.Time
}

func (q *Queries) UpsertSocialSettings(ctx context.Context, arg UpsertSocialSettingsParams) (SocialSetting, error) {
	row := q.db.QueryRowContext(ctx, upsertSocialSettings, arg.UserID, arg.Visible, arg.UpdatedAt)
	var i SocialSetting
	err := row.Scan(&i.UserID, &i.Visible, &i.UpdatedAt)
	return i, err
}
